BEGIN;
CREATE TABLE course_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid NOT NULL,term_code text NOT NULL,section_code text NOT NULL,instructor_user_id uuid REFERENCES users(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,delivery_mode text NOT NULL CHECK(delivery_mode IN ('online_async','online_live','hybrid')),status text NOT NULL DEFAULT 'scheduled',UNIQUE(tenant_id,term_code,section_code));
CREATE TABLE section_enrollments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),section_id uuid NOT NULL REFERENCES course_sections(id),student_user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN ('enrolled','withdrawn','completed','failed','incomplete')),grading_basis text NOT NULL CHECK(grading_basis IN ('letter','pass_fail')),final_grade text,credits_attempted numeric(5,2) NOT NULL CHECK(credits_attempted>=0),credits_earned numeric(5,2) NOT NULL DEFAULT 0 CHECK(credits_earned>=0),version integer NOT NULL DEFAULT 1,UNIQUE(section_id,student_user_id));
CREATE TABLE assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),section_id uuid NOT NULL REFERENCES course_sections(id),title text NOT NULL,points_possible numeric(10,2) NOT NULL CHECK(points_possible>0),weight numeric(7,4),due_at timestamptz NOT NULL,published_at timestamptz,version integer NOT NULL DEFAULT 1);
CREATE TABLE submissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),assignment_id uuid NOT NULL REFERENCES assignments(id),student_user_id uuid NOT NULL REFERENCES users(id),submitted_at timestamptz,status text NOT NULL CHECK(status IN ('draft','submitted','late','returned','accepted')),artifact_key text,UNIQUE(assignment_id,student_user_id));
CREATE TABLE grade_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),submission_id uuid NOT NULL REFERENCES submissions(id),points_earned numeric(10,2) NOT NULL CHECK(points_earned>=0),graded_by uuid NOT NULL REFERENCES users(id),approved_by uuid REFERENCES users(id),feedback text,graded_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1,supersedes_id uuid REFERENCES grade_entries(id));
CREATE TABLE class_meetings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),section_id uuid NOT NULL REFERENCES course_sections(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,attendance_method text NOT NULL CHECK(attendance_method IN ('live_checkin','faculty_verified','activity_evidence')),join_uri text,CHECK(ends_at>starts_at));
CREATE TABLE attendance_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),meeting_id uuid NOT NULL REFERENCES class_meetings(id),student_user_id uuid NOT NULL REFERENCES users(id),status text NOT NULL CHECK(status IN ('present','late','excused','absent')),minutes_present integer NOT NULL DEFAULT 0 CHECK(minutes_present>=0),evidence jsonb NOT NULL DEFAULT '{}',verified_by uuid REFERENCES users(id),verified_at timestamptz,UNIQUE(meeting_id,student_user_id));
CREATE TABLE degree_audits(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_user_id uuid NOT NULL REFERENCES users(id),program_id uuid NOT NULL,required_credits numeric(6,2) NOT NULL,earned_credits numeric(6,2) NOT NULL,calculated_gpa numeric(4,3),requirements jsonb NOT NULL,calculated_at timestamptz NOT NULL DEFAULT now(),approved_by uuid REFERENCES users(id),conferred_at timestamptz,CHECK(conferred_at IS NULL OR approved_by IS NOT NULL));
CREATE TABLE academic_interventions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),student_user_id uuid NOT NULL REFERENCES users(id),rule_code text NOT NULL,status text NOT NULL CHECK(status IN ('flagged','notified','reviewing','resolved','appealed','overturned')),evidence jsonb NOT NULL,assigned_to uuid REFERENCES users(id),finalized_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz,CHECK(status NOT IN ('resolved','overturned') OR finalized_by IS NOT NULL));
CREATE TABLE academic_appeals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id),intervention_id uuid NOT NULL REFERENCES academic_interventions(id),student_user_id uuid NOT NULL REFERENCES users(id),statement text NOT NULL,filed_at timestamptz NOT NULL DEFAULT now(),status text NOT NULL CHECK(status IN ('filed','under_review','granted','denied','remanded')),decided_by uuid REFERENCES users(id),decided_at timestamptz,CHECK(status NOT IN ('granted','denied','remanded') OR (decided_by IS NOT NULL AND decided_at IS NOT NULL)));
CREATE INDEX section_student_idx ON section_enrollments(tenant_id,student_user_id,status);CREATE INDEX assignment_due_idx ON assignments(tenant_id,due_at);CREATE INDEX attendance_student_idx ON attendance_records(tenant_id,student_user_id,status);CREATE INDEX intervention_queue_idx ON academic_interventions(tenant_id,status,created_at);
ALTER TABLE course_sections ENABLE ROW LEVEL SECURITY;ALTER TABLE section_enrollments ENABLE ROW LEVEL SECURITY;ALTER TABLE assignments ENABLE ROW LEVEL SECURITY;ALTER TABLE submissions ENABLE ROW LEVEL SECURITY;ALTER TABLE grade_entries ENABLE ROW LEVEL SECURITY;ALTER TABLE class_meetings ENABLE ROW LEVEL SECURITY;ALTER TABLE attendance_records ENABLE ROW LEVEL SECURITY;ALTER TABLE degree_audits ENABLE ROW LEVEL SECURITY;ALTER TABLE academic_interventions ENABLE ROW LEVEL SECURITY;ALTER TABLE academic_appeals ENABLE ROW LEVEL SECURITY;
CREATE POLICY course_sections_tenant ON course_sections USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY section_enrollments_tenant ON section_enrollments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY assignments_tenant ON assignments USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY submissions_tenant ON submissions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY grade_entries_tenant ON grade_entries USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY class_meetings_tenant ON class_meetings USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY attendance_records_tenant ON attendance_records USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY degree_audits_tenant ON degree_audits USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY academic_interventions_tenant ON academic_interventions USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);CREATE POLICY academic_appeals_tenant ON academic_appeals USING(tenant_id=current_setting('app.tenant_id',true)::uuid) WITH CHECK(tenant_id=current_setting('app.tenant_id',true)::uuid);
COMMIT;
